 if(o.type==='timer'){const p=state.plans.find(x=>x.id===id);const sec=workoutClock.elapsed+(workoutClock.running?Math.round((Date.now()-workoutClock.lastStarted)/1000):0);return modalWrap('Session timer',`<div class="notice"><strong>${p?E(planName(p)):'Easy session'}</strong><p>${p?E(p.main):'Use this timer for your session.'}</p></div><div style="text-align:center;margin:25px 0"><div id="timer-display" class="metric-large" role="timer" aria-live="off">${timeClock(sec)}</div><p class="muted small">Elapsed time while this page is active</p></div><div class="actions" style="justify-content:center"><button class="btn primary" data-action="toggle-timer">${workoutClock.running?'Pause':'Start'} timer</button><button class="btn secondary" data-action="reset-timer">Reset</button>${p?`<button class="btn ghost" data-action="new-log" data-id="${E(p.id)}">Log result</button>`:''}</div><p class="note-small" style="margin-top:20px">iOS may suspend timers in the background. Do not use this as a precise background interval alarm; a sports watch or phone timer is more reliable.</p>`);}
