function timeClock(sec){return `${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec/60)%60).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function render(){if(!state)return;document.body.classList.toggle('light',state.settings.theme==='light');screen=getScreen();app.innerHTML=state.settings.completed?pageshell(({today:todayScreen,calendar:calendarScreen,progress:progressScreen,boston:bostonScreen,settings:settingsScreen})[screen]()):onboardingScreen(); if(overlay&&state.settings.completed)app.insertAdjacentHTML('beforeend',modalHTML());if(toastMessage)app.insertAdjacentHTML('beforeend',`<div class="toast ${toastMessage.isError?'error':''}" role="status">${E(toastMessage.msg)}</div>`);}
let saveQueue=Promise.resolve();
async function mutate(fn){const task=saveQueue.then(async()=>{const candidate=structuredClone(state);fn(candidate);await saveState(candidate);state=candidate;render()});saveQueue=task.catch(()=>{});await task;}
function openModal(type,id=null,extra={}){overlay={type,id,...extra};render();const first=document.querySelector('.modal input:not([type=hidden]),.modal textarea,.modal select');first?.focus({preventScroll:true})}
function closeModal(){if(workoutClock.running)stopTimer();overlay=null;render()}
function stopTimer(){if(workoutClock.running){workoutClock.elapsed+=Math.max(0,Math.floor((Date.now()-workoutClock.lastStarted)/1000));workoutClock.running=false}if(workoutClock.intervalId){clearInterval(workoutClock.intervalId);workoutClock.intervalId=null}}
function timerTick(){const sec=workoutClock.elapsed+Math.floor((Date.now()-workoutClock.lastStarted)/1000);const display=document.querySelector('#timer-display');if(display)display.textContent=timeClock(sec)}
function toggleTimer(){if(workoutClock.running)stopTimer();else{workoutClock.lastStarted=Date.now();workoutClock.running=true;workoutClock.intervalId=setInterval(timerTick,500)}render()}
function inputVal(fd,key){return String(fd.get(key)||'').trim()}
function optionalNum(fd,key){const v=fd.get(key);return v===null||String(v).trim()===''?null:Number(v)}
function validNonnegative(val,name){if(!Number.isFinite(Number(val))||Number(val)<0)throw new Error(`${name} must be a valid nonnegative number.`)}
function selectedRunDays(fd){const ds=fd.getAll('runDays').map(Number).filter(n=>n>=0&&n<=6);if(ds.length<2||ds.length>4)throw new Error('Select between 2 and 4 running days.');return ds}
function applyProfile(st,fd,isNew=false){const ds=selectedRunDays(fd),stDate=inputVal(fd,'startDate');safeDate(stDate,'')||'';if(!/^\d{4}-\d{2}-\d{2}$/.test(stDate))throw new Error('Choose a valid training date.');
 st.settings.name=inputVal(fd,'name').slice(0,80);st.settings.startDate=stDate;st.settings.continuousMin=Number(inputVal(fd,'continuousMin')||0);st.settings.walkMin=Number(inputVal(fd,'walkMin')||0);st.settings.runDays=ds;st.settings.longDay=Number(inputVal(fd,'longDay')||6);st.settings.units=inputVal(fd,'units')==='km'?'km':'mi';
 if(!ds.includes(st.settings.longDay))st.settings.longDay=ds[ds.length-1];
 if(!isNew){st.settings.theme=inputVal(fd,'theme')==='light'?'light':'dark';st.settings.intensity=inputVal(fd,'intensity');st.settings.timezone=inputVal(fd,'timezone')||'America/New_York';st.settings.weeklyMiles=toMiles(Number(inputVal(fd,'weeklyMiles')||0),st.settings.units);st.settings.comfort=inputVal(fd,'comfort').slice(0,1500)}
 st.settings.completed=true;
}
async function submitForm(e){const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const fd=new FormData(f);const type=f.id;
 try{
 if(type==='onboarding-form'){await mutate(s=>{applyProfile(s,fd,true);const {block,plans}=generateBlock(s.settings,[],s.settings.startDate);s.blocks=[block];s.plans=plans});location.hash='#/today';message('Your first four-week training block is ready.');return;}
 if(type==='settings-form'){await mutate(s=>applyProfile(s,fd));message('Preferences saved. Existing calendar sessions were not rewritten.');return;}
 if(type==='phase-form'){const ph=inputVal(fd,'phase');if(!(ph in PHASES))throw new Error('Unknown training phase.');if(['half','marathon','boston'].includes(ph)&&ph!==state.settings.phase&&!confirm('These advanced phases require a consistent running base and good recovery. Change the phase for FUTURE blocks only?'))return;await mutate(s=>{s.settings.phase=ph});message('Next-block phase updated. Existing plans are unchanged.');return;}
 if(type==='log-form'){
  const distance=optionalNum(fd,'distance')??0,duration=optionalNum(fd,'duration');validNonnegative(distance,'Distance');validNonnegative(duration,'Duration');if(duration===null)throw new Error('Enter duration in minutes.');
  const date=inputVal(fd,'date'),type=inputVal(fd,'type');if(!['run','walk','runwalk','strength','cycling','elliptical','cross-training','recovery','race'].includes(type))throw new Error('Unknown workout type.');
  const details={date,type,distanceMiles:toMiles(distance,unit()),durationMin:duration,rpe:Number(inputVal(fd,'rpe')||3),energy:Number(inputVal(fd,'energy')||3),painFlag:fd.has('painFlag'),notes:inputVal(fd,'notes').slice(0,3000),runMin:optionalNum(fd,'runMin'),walkMin:optionalNum(fd,'walkMin'),avgHeartRate:optionalNum(fd,'avgHeartRate'),peakHeartRate:optionalNum(fd,'peakHeartRate'),soreness:optionalNum(fd,'soreness'),weather:inputVal(fd,'weather').slice(0,120),hydration:inputVal(fd,'hydration').slice(0,300),shoe:inputVal(fd,'shoe').slice(0,100),route:inputVal(fd,'route').slice(0,400)};
  if(!date||Number(details.distanceMiles)<0)throw new Error('Enter a valid date and distance.');
  await mutate(s=>{const existing=s.workouts.find(x=>x.id===overlay?.id);if(existing)Object.assign(existing,details);else s.workouts.push({id:uuid(),...details,plannedId:overlay?.plannedId||null,createdAt:new Date().toISOString()});});overlay=null;render();message('Workout saved. Your dashboard and charts are updated.');return;
 }
 if(type==='plan-form'){await mutate(s=>{const p=s.plans.find(x=>x.id===overlay?.id);if(!p)throw new Error('Planned session was not found.');Object.assign(p,{date:inputVal(fd,'date'),durationMin:Number(inputVal(fd,'duration')),type:inputVal(fd,'type'),main:inputVal(fd,'main').slice(0,1200),skipReason:inputVal(fd,'skipReason').slice(0,500),status:inputVal(fd,'status')});});overlay=null;render();message('Planned session updated.');return;}
 if(type==='race-form'){
 const dist=Number(inputVal(fd,'distance'));if(!Number.isFinite(dist)||dist<=0)throw new Error('Race distance must be positive.');const time=inputVal(fd,'finishTime'),finishSeconds=parseRaceTime(time);if(time&&!finishSeconds)throw new Error('Finish time format: H:MM:SS or MM:SS');
 const r={name:inputVal(fd,'name').slice(0,120),location:inputVal(fd,'location').slice(0,130),date:inputVal(fd,'date'),dateStatus:inputVal(fd,'dateStatus'),distanceMiles:toMiles(dist,unit()),registration:inputVal(fd,'registration'),preparation:inputVal(fd,'preparation'),bib:inputVal(fd,'bib').slice(0,40),finishSeconds,site:inputVal(fd,'site'),officialResults:inputVal(fd,'officialResults'),notes:inputVal(fd,'notes').slice(0,2400)};
 await mutate(s=>{const found=s.races.find(x=>x.id===overlay?.id);if(found)Object.assign(found,r);else s.races.push({id:uuid(),...r})});overlay=null;render();message('Race milestone saved.');return;
 }
 if(type==='charity-form'){
 const data={name:inputVal(fd,'name').slice(0,160),status:inputVal(fd,'status'),website:inputVal(fd,'website'),applicationUrl:inputVal(fd,'applicationUrl'),interestUrl:inputVal(fd,'interestUrl'),minimum:optionalNum(fd,'minimum'),goal:optionalNum(fd,'goal'),openDate:inputVal(fd,'openDate'),deadline:inputVal(fd,'deadline'),appliedAt:inputVal(fd,'appliedAt'),followUp:inputVal(fd,'followUp'),lastVerified:inputVal(fd,'lastVerified'),outcome:inputVal(fd,'outcome'),mission:inputVal(fd,'mission').slice(0,1200),notes:inputVal(fd,'notes').slice(0,3000),verified:fd.has('verified'),agreement:fd.has('agreement')};
 for(const k of ['minimum','goal'])if(data[k]!==null)validNonnegative(data[k],k);
 await mutate(s=>{const found=s.charities.find(x=>x.id===overlay?.id);if(found)Object.assign(found,data);else s.charities.push({id:uuid(),...data});});overlay=null;render();message('Charity application saved.');return;
 }
 if(type==='donation-form'){const amount=optionalNum(fd,'amount');if(amount===null||amount<=0)throw new Error('Amount must be greater than zero.');const data={date:inputVal(fd,'date'),amount,status:inputVal(fd,'status'),source:inputVal(fd,'source'),notes:inputVal(fd,'notes').slice(0,2000)};await mutate(s=>{const found=s.donations.find(x=>x.id===overlay?.id);if(found)Object.assign(found,data);else s.donations.push({id:uuid(),...data});});overlay=null;render();message('Contribution saved.');return;}
 if(type==='goal-form'){const goal=optionalNum(fd,'fundraisingGoal'),stretch=optionalNum(fd,'fundraisingStretch');validNonnegative(goal,'Fundraising minimum');validNonnegative(stretch,'Stretch goal');await mutate(s=>Object.assign(s.settings,{fundraisingGoal:goal,fundraisingStretch:stretch,fundraisingDeadline:inputVal(fd,'fundraisingDeadline')}));overlay=null;render();message('Fundraising targets updated.');return;}
 if(type==='why-form'){await mutate(s=>{s.myWhy=inputVal(fd,'myWhy').slice(0,10000)});overlay=null;render();message('Your reflection has been saved locally.');return;}
 }catch(err){console.error(err);message(err.message||'Could not process the form.',true);}
}
async function exportBackup(){const text=JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2);const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`road-to-boylston-backup-${today()}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),6000);message('Backup downloaded. Store a copy somewhere safe.');}
async function importBackup(){const el=document.querySelector('#backup-file'),mode=document.querySelector('#import-mode')?.value||'merge',file=el?.files?.[0];if(!file){message('Select a JSON backup first.',true);return}if(file.size>15*1024*1024){message('Backup exceeds 15 MB.',true);return}try{const incoming=validateBackup(JSON.parse(await file.text()));if(mode==='replace'&&!confirm('Replace ALL local training, charities, donations and notes with the imported backup? This cannot be undone. Export a backup first.'))return;await mutate(s=>{const next=mode==='replace'?sanitizeState(incoming):mergeStates(s,incoming);Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,next)});message(`Backup ${mode==='replace'?'restored':'merged'} successfully.`)}catch(e){message(`Backup rejected: ${e.message}`,true)}}
async function createNextBlock(repeat=false){const review=suggestNextBlock(state);if(!repeat&&!review.canAdvance&&state.blocks.length){message('Review your current block and recovery first, or use the easier repeat option.',true);return}
 const start=nextBlockStart(state),conflict=state.plans.some(p=>p.date>=start&&p.date<=addDays(start,27));if(conflict){message('A plan already exists in that date range.',true);return}
 if(['half','marathon','boston'].includes(state.settings.phase)){const count=state.workouts.filter(isRun).length;if(count<12&&!confirm('Fewer than 12 runs are logged. Advanced training is not recommended without a consistent aerobic base. Create this block anyway?'))return;}
 if(!confirm(`Create ${repeat?'an easier repeat':'the next'} four-week training block beginning ${dateLabel(start)}? You can edit sessions afterward.`))return;
 await mutate(s=>{let generated=generateBlock(s.settings,s.blocks,start);if(repeat){const last=[...s.blocks].sort((a,b)=>b.startDate.localeCompare(a.startDate))[0];if(last){const prev=s.plans.filter(p=>p.blockId===last.id);if(prev.length){const delta=daysBetween(last.startDate,start),id=uuid();generated={block:{id,phase:last.phase,startDate:start,endDate:addDays(start,27),approvedAt:new Date().toISOString(),label:'Repeat / easier block'},plans:prev.map(p=>({...p,id:uuid(),blockId:id,date:addDays(p.date,delta),status:'planned',skipReason:'',durationMin:Math.round((p.durationMin||0)*.85),main:p.main+' Keep effort gentle; repeat or reduce as needed.'}))};}}}
 s.blocks.push(generated.block);s.plans.push(...generated.plans);});message(`${repeat?'Easier repeat':'Next'} block added to your calendar.`);}
async function deleteItem(collection,id,description){if(!confirm(`Delete this ${description}? This cannot be undone unless you restore a backup.`))return;await mutate(s=>{s[collection]=s[collection].filter(x=>x.id!==id)});overlay=null;render();message(`${labelCase(description)} deleted.`)}
async function onAction(e){const el=e.target.closest?.('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
 if(action==='close-background'){if(e.target===el)closeModal();return}
 if(action==='close-modal'){closeModal();return}
 if(action==='navigate'){go(el.dataset.screen);window.scrollTo({top:0,behavior:'instant'});return}
 if(action==='new-log'){stopTimer();openModal('log',null,{plannedId:id||null,date:el.dataset.date});return}
 if(action==='edit-log'){openModal('log',id);return}
 if(action==='new-race'||action==='edit-race'){openModal('race',id);return}
 if(action==='new-charity'||action==='edit-charity'){openModal('charity',id);return}
 if(action==='new-donation'||action==='edit-donation'){openModal('donation',id);return}
 if(action==='fundraising-goals'){openModal('fundraising-goals');return}
 if(action==='edit-why'){openModal('why');return}
 if(action==='draft-charity'){openModal('draft-charity');return}
 if(action==='edit-plan'){openModal('plan',id);return}
 if(action==='timer'){workoutClock={running:false,elapsed:0,lastStarted:0,intervalId:null};openModal('timer',id);return}
 if(action==='toggle-timer'){toggleTimer();return}
 if(action==='reset-timer'){stopTimer();workoutClock.elapsed=0;render();return}
 if(action==='cal-prev'||action==='cal-next'){const step=action==='cal-prev'?-1:1;if(calendarMode==='month'){calendarAnchor=monthShift(calendarAnchor,step);selectedDate=calendarAnchor}else{selectedDate=addDays(selectedDate,step*7);calendarAnchor=monthStart(selectedDate)}render();return}
 if(action==='cal-today'){calendarAnchor=monthStart(today(state.settings.timezone));selectedDate=today(state.settings.timezone);render();return}
 if(action==='cal-mode'){calendarMode=el.dataset.mode;render();return}
 if(action==='select-day'){selectedDate=el.dataset.date;render();return}
 if(action==='chart-mode'){chartMode=el.dataset.mode;render();return}
 if(action==='boston-tab'){bostonTab=el.dataset.tab;render();return}
 if(action==='save-entry-stage'){const value=document.querySelector('#f-entryStatus')?.value;if(!entryStages.some(a=>a[0]===value))return;await mutate(s=>{s.boston.entryStatus=value});message('Entry stage saved.');return}
 if(action==='boston-toggle'){await mutate(s=>{s.boston[el.dataset.key]=el.checked});return}
 if(action==='generate-block'){await createNextBlock();return}
 if(action==='repeat-block'){await createNextBlock(true);return}
 if(action==='delete-log'){await deleteItem('workouts',id,'workout');return}
 if(action==='delete-race'){await deleteItem('races',id,'race');return}
 if(action==='delete-charity'){await deleteItem('charities',id,'charity');return}
 if(action==='delete-donation'){await deleteItem('donations',id,'donation');return}
 if(action==='export'){await exportBackup();return}
 if(action==='import'){await importBackup();return}
 if(action==='copy-charity-draft'){const val=document.querySelector('#charity-draft')?.value;if(val){try{await navigator.clipboard.writeText(val);message('Charity statement copied.')}catch{document.querySelector('#charity-draft')?.select();message('Select and copy the text in the draft field.')}}return}
 if(action==='reset-data'){if(!confirm('Permanently delete all locally saved workouts, races, charities and preferences? This cannot be undone. Export first.'))return;if(!confirm('Last confirmation: wipe this browser’s Road to Boylston data?'))return;await saveState(initialState());state=await loadState();overlay=null;location.hash='#/today';render();message('Local app reset.');return}
}
app.addEventListener('click',e=>{onAction(e).catch(err=>{console.error(err);message(err.message||'An unexpected error occurred.',true)})});
app.addEventListener('submit',e=>{submitForm(e)});
app.addEventListener('input',e=>{if(e.target.closest('#log-form')&&['distance','duration'].includes(e.target.name)){const f=e.target.form;const dist=Number(f?.elements?.namedItem('distance')?.value||0),dur=Number(f?.elements?.namedItem('duration')?.value||0),view=f.querySelector('#pace-preview');if(view)view.textContent=dist>0&&dur>0?`Calculated average pace: ${formatPace(calculatePace(toMiles(dist,unit()),dur,unit()))} per ${unit()}`:'Average pace will appear when you enter distance and duration.'}});
window.addEventListener('hashchange',()=>{screen=getScreen();overlay=null;stopTimer();render();window.scrollTo(0,0)});
window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay)closeModal()});
async function init(){try{state=sanitizeState(await loadState());const t=today(state.settings.timezone);calendarAnchor=monthStart(t);selectedDate=t;screen=getScreen();render();if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(err=>console.warn('Offline service worker unavailable:',err));}}
 catch(err){console.error(err);app.innerHTML=`<div class="onboarding"><div class="onboarding-panel"><h1>We couldn't open local storage.</h1><p>${E(err.message)}</p><p>Try a normal, non-private browser window with storage enabled. We won't start a new database over your data.</p></div></div>`;}}
init();
